// Hash function that intentionally lets int multiplication overflow,
// relying on 'modular' wraparound. This is UB per C++17/20 standards —
// the compiler may optimize the entire function away.
#include <cstdint>

int hash_djb2_signed(const char* s) {
    int h = 5381;
    if (!s) return 0;
    while (*s) {
        // h * 33 + *s — overflows for long strings.
        // GCC/Clang historically wrap; UBSan flags this; -fwrapv saves it.
        h = h * 33 + *s;
        ++s;
    }
    return h;
}
